local A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local P=""
local K1,K2=35,241
local function D(s)
local o={}
local i=1
while i<=#s do
local a=A:find(s:sub(i,i),1,true) or 0
local b=A:find(s:sub(i+1,i+1),1,true) or 0
local c=A:find(s:sub(i+2,i+2),1,true) or 0
local d=A:find(s:sub(i+3,i+3),1,true) or 0
local n=(a-1)*262144+(b-1)*4096+(c-1)*64+(d-1)
o[#o+1]=string.char(math.floor(n/65536)%256)
if s:sub(i+2,i+2)~="=" then o[#o+1]=string.char(math.floor(n/256)%256) end
if s:sub(i+3,i+3)~="=" then o[#o+1]=string.char(n%256) end
i=i+4
end
return table.concat(o)
end
local R=D(P)
local O={}
for i=1,#R do
local v=bxor(string.byte(R,i),K2)
v=bxor(v,(i-1)%256)
v=bxor(v,K1)
O[i]=string.char(v)
end
loadstring(table.concat(O))()